{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Posaconazole, a large lipophilic azole with a triazole heterocycle and high molecular weight, has an absolute oral bioavailability of about 50% in healthy volunteers with a delayed-release tablet, supporting high F for the query's similar azole/large-lipophilic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Atazanavir, a large peptidomimetic HIV protease inhibitor with high molecular weight and multiple polar groups, has an absolute oral bioavailability of 68% (57–80%) in humans, supporting high F despite unfavorable physicochemical priors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Perindopril, a zwitterionic ACE inhibitor prodrug containing a carboxylic acid and amine, has an absolute oral bioavailability of 66% in humans, supporting high F for a zwitterionic, moderately large molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Ursodeoxycholic acid, a steroid carboxylic acid, has systemic availability of 78–87% in cirrhotic patients, supporting high F for the query's steroid-like carboxylic acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Iclepertin, a lipophilic clinical compound with high molecular weight and multiple aromatic/heteroaromatic groups, has an absolute oral bioavailability of 71.6% in humans, supporting high F for a large lipophilic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Cilomilast, a lipophilic carboxylic acid, has an absolute oral bioavailability of 96% (range 92–102%) in healthy volunteers, supporting high F for a carboxylic-acid-containing lipophilic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pentazocine has an absolute oral bioavailability of 18% in healthy subjects, providing contradictory evidence that some lipophilic drugs with extensive first-pass metabolism can fall below the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Posaconazole oral suspension in pediatric patients had an absolute bioavailability of 16.5%, showing that formulation and patient population can reduce F below 20%, though adult tablet data are higher.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "KNI-272, a large peptidomimetic HIV protease inhibitor, had a mean absolute bioavailability of only 12% in children, illustrating that high interpatient/age variability can lead to low F in some settings.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite unfavorable physicochemical priors (high MW, very high logP, high TPSA, zwitterionic character), the preponderance of transferable experimental evidence from large lipophilic and zwitterionic drugs—posaconazole, atazanavir, perindopril, UDCA, iclepertin, and cilomilast—shows absolute oral bioavailability at or above 50%. The few low-F outliers are mostly formulation-, age-, or population-dependent. Therefore, F ≥ 20% is better supported, and the prediction is high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for this exact scaffold.",
    "Solubility and dissolution behavior of the query are not experimentally measured; high logP suggests possible formulation dependence.",
    "First-pass metabolism and transporter-mediated efflux for the query are unknown.",
    "Pediatric and special-population low-F results may not extrapolate to typical adult oral dosing."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

